    authored.set("This shows y=x+A is a solution of the ordinary differential equation dy/dx=1.", [{"en": "This shows y=x+A is a solution of the ordinary differential equation dy/dx=1.", "ur": "اس سے ظاہر ہوتا ہے کہ y=x+A، عام تفریقی مساوات dy/dx=1 کا حل ہے۔", "ps": "دا ښيي چې y=x+A د عادي تفاضلي معادلې dy/dx=1 حل دی."}]);
