    authored.set("Determine the orthogonal trajectories of the family of curves (circles) x²+y²=c.", [{"en": "Determine the orthogonal trajectories of the family of curves (circles) x²+y²=c.", "ur": "منحنیوں (دائروں) کے خاندان x²+y²=c کے عمودی متقاطع منحنیات معلوم کریں۔", "ps": "د منحنیو (دایرو) د کورنۍ x²+y²=c عمودي متقاطع مسیرونه ومومئ."}]);
    authored.set("To determine the orthogonal trajectories, determine the slope (derivative) of the family of circles with respect to x:", [{"en": "To determine the orthogonal trajectories, determine the slope (derivative) of the family of circles with respect to x:", "ur": "عمودی متقاطع منحنیات کے لیے دائروں کے خاندان کی x کے لحاظ سے ڈھلوان (مشتق) معلوم کریں:", "ps": "د عمودي متقاطع مسیرونو د موندلو لپاره د دایرو د کورنۍ میل (مشتق) د x په نسبت ومومئ:"}]);
    authored.set("Use the circle slope to obtain the other family of curves G of orthogonal trajectories:", [{"en": "Use the circle slope to obtain the other family of curves G of orthogonal trajectories:", "ur": "دائرے کی ڈھلوان سے عمودی متقاطع منحنیوں کا دوسرا خاندان G حاصل کریں:", "ps": "د دایرې میل وکاروئ څو د عمودي متقاطع منحنیو بله کورنۍ G ترلاسه کړئ:"}]);
    authored.set("Thus the family G represents a family of homogeneous straight lines passing through the origin. This is the result expected since the radii of a circle are homogeneous lines y=Cx, C any real number, perpendicular to the lines tangent to a circle.", [{"en": "Thus the family G represents a family of homogeneous straight lines passing through the origin. This is the result expected since the radii of a circle are homogeneous lines y=Cx, C any real number, perpendicular to the lines tangent to a circle.", "ur": "یوں خاندان G مبدا سے گزرنے والی ہم جنس سیدھی لکیروں کا خاندان ہے۔ یہی متوقع نتیجہ ہے کیونکہ دائرے کے رداس ہم جنس لکیریں y=Cx ہیں، جہاں C کوئی حقیقی عدد ہے، اور یہ دائرے کے مماس پر عمود ہیں۔", "ps": "نو کورنۍ G له مبدا څخه د تېرېدونکو همجنسو مستقیمو کرښو کورنۍ ښيي. همدا تمه شوې پایله ده، ځکه د دایرې شعاعګانې همجنسې کرښې y=Cx دي، چې C هر حقیقي عدد دی، او د دایرې پر مماس کرښو عمودي دي."}]);
